/**
 * NHL model history, written by the research scripts (nhl_track.py) — do not edit by hand.
 * Each season replayed walk-forward with the v2 model (only earlier games, coefficients and calibration
 * fitted on earlier seasons). Units are at real prices: closing moneyline (winner), posted puck line and
 * total prices, and the OPENING moneyline for tracked edges. `units: null` = the season's prices don't
 * allow it (2023-24 Unibet lists the 3-way regulation moneyline; 2024-25 has no free odds).
 */
export interface NhlHistoryRecord {
  wins: number;
  losses: number;
  pushes: number;
  /** Units on the picks that had a price (null when none did). */
  units: number | null;
  /** How many of the picks had a price. */
  priced: number;
}

export interface NhlHistorySeason {
  season: number;
  label: string;
  /** Where the prices come from: SBR (Sportsbook Reviews Online), Unibet / DraftKings (via ESPN), or none. */
  source: string;
  winner: NhlHistoryRecord | null;
  puckLine: NhlHistoryRecord | null;
  total: NhlHistoryRecord | null;
  tracked: NhlHistoryRecord | null;
  movedToward: number;
  movedAgainst: number;
}

export interface NhlWatchSeason extends NhlHistoryRecord {
  season: number;
  label: string;
}

